import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';

// 1. Load tokens generated by PerformanceTestSeeder
const users = new SharedArray('users', function () {
    return JSON.parse(open('../tokens.json'));
});

// 2. Configuration
export const options = {
    scenarios: {
        // A. Load Test: Consistent traffic
        load_test: {
            executor: 'ramping-vus',
            startVUs: 0,
            stages: [
                { duration: '1m', target: 20 }, // Ramp up to 20 users
                { duration: '3m', target: 20 }, // Stay at 20 users
                { duration: '1m', target: 0 },  // Ramp down
            ],
            gracefulStop: '30s',
        },
        // B. Spike Test: Sudden burst
        /*
        spike_test: {
            executor: 'per-vu-iterations',
            vus: 100,
            iterations: 1,
            startTime: '2m',
        },
        */
    },
    thresholds: {
        http_req_duration: ['p(95)<500'], // 95% of requests must be under 500ms
        http_req_failed: ['rate<0.01'],   // Error rate must be less than 1%
    },
};

const BASE_URL = 'http://localhost:8000/api'; // Adjust to your local/staging URL

export default function () {
    // Pick a random user from the pool
    const user = users[Math.floor(Math.random() * users.length)];
    const params = {
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'Authorization': `Bearer ${user.token}`,
        },
    };

    // --- Task 1: Search Foods ---
    let res = http.get(`${BASE_URL}/foods?search=chicken`, params);
    check(res, { 'search foods status is 200': (r) => r.status === 200 });
    sleep(1);

    // --- Task 2: Get History ---
    res = http.get(`${BASE_URL}/food-logs`, params);
    check(res, { 'get logs status is 200': (r) => r.status === 200 });
    sleep(1);

    // --- Task 3: Post Food Log ---
    const payload = JSON.stringify({
        nama_makanan: 'Grilled Chicken Breast',
        weight: 150,
        kcal: 250,
        protein: 30,
        carbs: 0,
        fat: 10,
        category: 'Protein',
        jenis: 'Lunch'
    });
    res = http.post(`${BASE_URL}/food-logs`, payload, params);
    check(res, { 'post food log status is 201': (r) => r.status === 201 });
    
    sleep(Math.random() * 3 + 2); // Wait 2-5 seconds between "user actions"
}
